content.text:
请对以下 case 进行三维加权评分。

=== case_id ===
Case-01-low-power-010

=== 用户原始指令 (query.txt) ===
搞个省电模式卡片 文字叠在图上 显示剩多少电 点了能跳应用

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "搞个省电模式卡片 文字叠在图上 显示剩多少电 点了能跳应用",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.settings",
        "abilityName": "com.huawei.hmos.settings.MainAbility",
        "uri": "battery"
      }
    }
  ],
  "dataModelSchema": {
    "power": {
      "title": {
        "type": "string",
        "description": "省电模式卡片标题",
        "sampleValue": "省电模式"
      },
      "batteryPercentText": {
        "type": "string",
        "description": "当前剩余电量的展示文本",
        "sampleValue": "18%"
      },
      "batteryPercentValue": {
        "type": "number",
        "description": "当前剩余电量百分比数值，用于进度展示",
        "sampleValue": 18
      },
      "batteryTotal": {
        "type": "number",
        "description": "电量百分比总量",
        "sampleValue": 100
      },
      "statusText": {
        "type": "string",
        "description": "当前省电模式状态说明",
        "sampleValue": "低电量，已建议省电"
      },
      "estimateText": {
        "type": "string",
        "description": "省电模式下的续航提示",
        "sampleValue": "预计可多用 2 小时"
      },
      "actionLabel": {
        "type": "string",
        "description": "跳转到电池设置的动作文案",
        "sampleValue": "查看电池"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_save_power.png",
      "description": "省电图标，适合低电模式卡片中作为主视觉背景，表达节能与延长续航。"
    }
  ]
}

